-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
  hl.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ 0")
  -- Portal de Hyprland para compartir pantalla (Discord, etc.): sin el,
  -- el selector de captura sale vacio. Ademas se reinicia el portal
  -- principal para que registre ScreenCast/Screenshot (carrera de arranque:
  -- si arranca antes que la implementacion, no los expone).
  hl.exec_cmd("systemctl --user start xdg-desktop-portal-hyprland")
  hl.exec_cmd("sleep 1 && systemctl --user restart xdg-desktop-portal")
  hl.exec_cmd("LOCPATH=/home/jairo/.locales waybar")
  -- Daemon de minimize: escucha socket2 y emula el minimize (Hyprland no
  -- oculta ventanas nativamente). El taskbar envia set_minimized y el daemon
  -- mueve al special:minimized, restaurando al hacer clic sobre el icono del
  -- taskbar. Ya no flota ventanas: todo se encuadra (mosaico) por defecto.
  hl.exec_cmd("systemd-run --user --unit=hypr-minimize-daemon "
    .. "--property=StandardOutput=journal --property=StandardError=journal "
    .. "python3 /home/jairo/.local/bin/minimize-daemon.py")
  -- Fondo de pantalla: hyprpaper (estáticos) + wallpaper engine (workshop)
  -- init_wallpaper.sh regenera la config y arranca hyprpaper si hay estado guardado;
  -- si no, arranca hyprpaper con la config por defecto.
  hl.exec_cmd("pgrep -x hyprpaper >/dev/null || hyprpaper >/dev/null 2>&1 &")
  hl.exec_cmd("sleep 2 && /home/jairo/.config/eww/scripts/init_wallpaper.sh")
  -- Genera eww.yuck con la lista de fondos incrustada (SUPER+W)
  hl.exec_cmd("python3 /home/jairo/.config/eww/scripts/list_wallpapers.py >/dev/null 2>&1")
  -- Daemon de eww para el menú de fondos (abrir con SUPER+W)
  hl.exec_cmd("pgrep -x eww >/dev/null || eww daemon >/dev/null 2>&1 &")
end)


