hl.config({
    misc = {
        force_default_wallpaper = -1,    -- Set to 0 or 1 to disable the anime mascot wallpapers
        disable_hyprland_logo   = false, -- If true disables the random hyprland logo / anime girl background. :(
        disable_splash_rendering = true, -- Quita las frases que aparecen abajo del todo (ej: "To rice, or not to rice")
        -- Con una ventana expandida (maximizada) o fullscreen, al abrir o
        -- enfocar otra ventana en mosaico esta hereda el estado (queda
        -- encima) en vez de quedarse oculta debajo. Las flotantes (lanzador,
        -- barras) solo se suben al frente, sin robar el estado.
        on_focus_under_fullscreen = 1,
        -- Al cerrar la ventana que tiene el estado expandido/fullscreen, la
        -- siguiente ventana enfocada lo hereda: abres algo encima de la
        -- expandida y al cerrarlo la anterior vuelve sola a pantalla completa.
        exit_window_retains_fullscreen = 1,
    },
})

-- Calidad de imagen maxima que da el monitor (1920x1080).
-- El monitor usa escala 1.5 (fraccional); sin esto, las apps XWayland
-- (Steam, juegos) se renderizan a baja resolucion y el compositor las
-- escala, dando un aspecto pixelado.
hl.config({
    xwayland = {
        -- Renderiza las ventanas XWayland a escala nativa (nitidas) en
        -- lugar de que el compositor las estire con el factor 1.5.
        force_zero_scaling = true,
    },
})

hl.config({
    render = {
        -- Permite que las ventanas fullscreen (juegos) se presenten
        -- directamente sin pasar por el compositor: maxima nitidez.
        direct_scanout = true,
        -- Evita que texturas mas pequenas que el area se estiren borrosas.
        expand_undersized_textures = false,
    },
})


