-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Las ventanas se encuadran (mosaico) automáticamente: cada aplicación al
-- abrirse ocupa la mitad del hueco disponible y, con 3, 4, 5... ventanas,
-- se van repartiendo la pantalla sola. El daemon minimize-daemon.py solo
-- gestiona minimizar/restaurar desde el taskbar.

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Ventanas expandidas (estado nativo maximized): sin borde, sin esquinas
-- redondeadas ni sombra, para que se distingan del mosaico normal y no
-- parezcan flotantes. La regla es dinamica: se aplica al maximizar y se
-- revierte sola al restaurar (tambien cuando otra ventana hereda el estado).
hl.window_rule({
    name        = "maximized-flush",
    match       = { fullscreen_state_internal = 1 },
    border_size = 0,
    rounding    = 0,
    no_shadow   = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Desplegables de la barra (volumen, brillo, monitor, spotify, sistema):
-- flotantes, con las mismas esquinas y sin borde del compositor — el
-- contorno morado lo pinta su propio CSS, uno de Hyprland lo duplicaria.
hl.window_rule({
    name     = "float-bar-popups",
    match    = { class = "^(volume_popup|brightness_popup|monitor_popup|spotify_popup|system_popup)\\.py$" },
    float    = true,
    rounding = 12,
    border_size = 0,
})

-- Kitty sin desenfoque del compositor: la terminal conserva su
-- translucidez pero no desenfoca lo que hay detrás.
hl.window_rule({
    name    = "kitty-no-blur",
    match   = { class = "^kitty$" },
    no_blur = true,
})

-- Lanzador de aplicaciones (wofi): flotante, sin bordes del compositor
-- (el contorno morado lo pinta su CSS) y con esquinas a juego con su radio.
-- El desenfoque nacarado sale solo del blur global + su fondo translúcido.
hl.window_rule({
    name        = "float-wofi",
    match       = { class = "^wofi$" },
    float       = true,
    rounding    = 14,
    border_size = 0,
})

-- Explorador de archivos (nautilus) con el mismo estilo que wofi: flotante,
-- sin bordes del compositor y esquinas a juego. La transparencia la pinta el
-- propio GTK4 vía CSS (lamina rgba), sin opacity del compositor: asi el texto
-- no se apaga.
hl.window_rule({
    name        = "float-nautilus",
    match       = { class = "^(nautilus|org\\.gnome\\.Nautilus)$" },
    float       = true,
    rounding    = 14,
    border_size = 0,
})

-- Cristal nacarado en el lanzador (nwg-drawer): desenfoca el fondo tras él
hl.layer_rule({
    name  = "drawer-blur",
    match = { namespace = "^nwg-drawer$" },
    blur  = true,
})

-- Selector de fondos (SUPER+X): ventana flotante sin bordes.
-- La posición (abajo-centro) la fija el propio picker en tiempo real
-- (logical_size), así que no se define un move estático aquí.
hl.window_rule({
    name    = "float-wallpaper-picker",
    match   = { class = "wallpaper-menu" },
    float   = true,
    no_anim = true,
    rounding = 12,
})

-- Al recibir el foco una ventana (p. ej. al hacer clic sobre ella),
-- se sube al frente para que nunca quede oculta bajo otra ventana.
-- En ventanas en mosaico esto no tiene efecto (alterzorder es no-op).
hl.bind(mainMod .. " + T", function () hl.window.alter_zorder({ mode = "top" }) end, { description = "Llevar la ventana activa al frente" })

-- Sober (Roblox): el reto "Verifying you're not a bot" se abre como una
-- ventana aparte titulada "Security", creada por el proceso sober_services
-- (el WebView de WebKit). En mosaico Hyprland la estruja junto al resto de
-- ventanas del espacio y el diálogo queda inservible, así que la sacamos
-- flotante y centrada con un tamaño de diálogo razonable.
hl.window_rule({
    name   = "float-sober-security",
    match  = { class = "org\\.vinegarhq\\.Sober", title = "^Security$" },
    float  = true,
    size   = "560 700",
    center = true,
})

-- pavucontrol-qt (F9): flotante y centrada para que no quede detrás de las
-- ventanas en mosaico.
hl.window_rule({
    name   = "float-pavucontrol",
    match  = { class = "pavucontrol-qt" },
    float  = true,
    size   = "900 700",
    center = true,
})

-- ALT + TAB: pasa a la siguiente ventana y la expande (maximizada nativa).
-- Si ya hay una expandida/fullscreen, la ventana enfocada hereda el estado
-- y queda encima. Para volver a encuadrarla: SUPER + ESPACIO sobre ella.
hl.bind("ALT + TAB",         hl.dsp.exec_cmd("/home/jairo/.local/bin/alt-tab-expand.py"),        { description = "Siguiente ventana al frente (expandida)" })
hl.bind("ALT + SHIFT + TAB", hl.dsp.exec_cmd("/home/jairo/.local/bin/alt-tab-expand.py --prev"), { description = "Ventana anterior al frente (expandida)" })
